void AutoclickClientInterceptorForTesting::BindAutoclick(BindAutoclickCallback callback) {
  GetForwardingInterface()->BindAutoclick(std::move(callback));
}
AutoclickClientAsyncWaiter::AutoclickClientAsyncWaiter(
    AutoclickClient* proxy) : proxy_(proxy) {}

AutoclickClientAsyncWaiter::~AutoclickClientAsyncWaiter() = default;

void AutoclickClientAsyncWaiter::BindAutoclick(
    ::mojo::PendingReceiver<Autoclick>* out_autoclick_receiver) {
  base::RunLoop loop;
  proxy_->BindAutoclick(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo::PendingReceiver<Autoclick>* out_autoclick_receiver
,
             ::mojo::PendingReceiver<Autoclick> autoclick_receiver) {*out_autoclick_receiver = std::move(autoclick_receiver);
            loop->Quit();
          },
          &loop,
          out_autoclick_receiver));
  loop.Run();
}

::mojo::PendingReceiver<Autoclick> AutoclickClientAsyncWaiter::BindAutoclick(
    ) {
  ::mojo::PendingReceiver<Autoclick> async_wait_result;
  BindAutoclick(&async_wait_result);
  return async_wait_result;
}






